import type { FastifyInstance } from 'fastify'
import AdmZip from 'adm-zip'
import { and, eq, gt, isNull } from 'drizzle-orm'
import { db } from '../db/client.js'
import { exportLinks, users, vaults, vaultShares } from '../db/schema.js'
import { generateToken, hashToken } from '../auth/tokens.js'
import { logSecurityEvent } from '../auth/security-events.js'
import { resolveAccess, atLeast } from '../vaults/permissions.js'
import { createNote, readNote, splitPath } from '../notes/store.js'
import { parseNote, serializeNote, OkfValidationError } from '../notes/okf.js'
import { buildInstanceBackup, buildVaultZip, type VaultManifest } from './archive.js'

const LINK_TTL_MS = Number(process.env.EXPORT_LINK_TTL_HOURS ?? 24) * 60 * 60 * 1000

/** Export requires edit/owner (spec 7): a copy outlives later revocation. */
async function guardExport(userId: string, vaultId: string): Promise<boolean> {
  return atLeast(await resolveAccess(userId, vaultId), 'edit')
}

export function exportRoutes(app: FastifyInstance) {
  // Sessionless by design: anyone with a valid link inside its window.
  app.get<{ Params: { token: string } }>('/export-links/:token', async (req, reply) => {
    const link = (
      await db
        .select()
        .from(exportLinks)
        .where(
          and(
            eq(exportLinks.tokenHash, hashToken(req.params.token)),
            isNull(exportLinks.revokedAt),
            gt(exportLinks.expiresAt, new Date()),
          ),
        )
    )[0]
    if (!link) return reply.code(404).send({ error: 'not found' })
    const zip = await buildVaultZip(link.vaultId)
    return reply
      .header('content-type', 'application/zip')
      .header('content-disposition', 'attachment; filename="vault-export.zip"')
      .send(zip)
  })

  app.register(async (authed) => {
    authed.addHook('preHandler', authed.requireAuth)

    authed.get<{ Params: { id: string; '*': string } }>(
      '/vaults/:id/export/note/*',
      async (req, reply) => {
        if (!(await guardExport(req.user!.id, req.params.id))) {
          return reply.code(404).send({ error: 'not found' })
        }
        splitPath(req.params['*'])
        const note = await readNote(req.params.id, req.params['*'])
        if (!note) return reply.code(404).send({ error: 'note not found' })
        // Exactly as stored: frontmatter + body, no transformation.
        return reply
          .header('content-type', 'text/markdown')
          .header(
            'content-disposition',
            `attachment; filename="${req.params['*'].split('/')[1]}.md"`,
          )
          .send(serializeNote({ frontmatter: note.frontmatter, body: note.body }))
      },
    )

    authed.get<{ Params: { id: string } }>('/vaults/:id/export', async (req, reply) => {
      if (!(await guardExport(req.user!.id, req.params.id))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const zip = await buildVaultZip(req.params.id)
      await logSecurityEvent({
        type: 'vault_exported',
        actorUserId: req.user!.id,
        detail: { vaultId: req.params.id },
      })
      return reply
        .header('content-type', 'application/zip')
        .header('content-disposition', 'attachment; filename="vault-export.zip"')
        .send(zip)
    })

    authed.post<{ Params: { id: string } }>('/vaults/:id/export-links', async (req, reply) => {
      if (!(await guardExport(req.user!.id, req.params.id))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const token = generateToken()
      const [link] = await db
        .insert(exportLinks)
        .values({
          vaultId: req.params.id,
          createdBy: req.user!.id,
          tokenHash: hashToken(token),
          expiresAt: new Date(Date.now() + LINK_TTL_MS),
        })
        .returning()
      // Raw token returned once; only its hash is stored.
      return { id: link!.id, token, expiresAt: link!.expiresAt }
    })

    authed.delete<{ Params: { id: string; linkId: string } }>(
      '/vaults/:id/export-links/:linkId',
      async (req, reply) => {
        if (!(await guardExport(req.user!.id, req.params.id))) {
          return reply.code(404).send({ error: 'not found' })
        }
        const [revoked] = await db
          .update(exportLinks)
          .set({ revokedAt: new Date() })
          .where(
            and(eq(exportLinks.id, req.params.linkId), eq(exportLinks.vaultId, req.params.id)),
          )
          .returning()
        if (!revoked) return reply.code(404).send({ error: 'link not found' })
        return { status: 'revoked' }
      },
    )

    authed.post('/import', async (req, reply) => {
      const file = await req.file()
      if (!file) return reply.code(400).send({ error: 'archive file required' })
      const buffer = await file.toBuffer()
      let zip: AdmZip
      try {
        zip = new AdmZip(buffer)
      } catch {
        return reply.code(400).send({ error: 'not a valid zip archive' })
      }
      const manifestEntry = zip.getEntry('manifest.json')
      if (!manifestEntry) return reply.code(400).send({ error: 'manifest.json missing' })
      const manifest = JSON.parse(manifestEntry.getData().toString('utf8')) as VaultManifest

      const [vault] = await db
        .insert(vaults)
        .values({
          name: manifest.name ?? 'Imported vault',
          ownerId: req.user!.id,
          mergeable: Boolean(manifest.mergeable),
        })
        .returning()

      const skipped: string[] = []
      let imported = 0
      for (const entry of zip.getEntries()) {
        if (entry.isDirectory || !entry.entryName.endsWith('.md')) continue
        const path = entry.entryName.replace(/\.md$/, '')
        try {
          const { type, name } = splitPath(path)
          const parsed = parseNote(entry.getData().toString('utf8'))
          // Same shared validation write path as every other write.
          await createNote(
            vault!.id,
            { type, name, frontmatter: parsed.frontmatter, body: parsed.body },
            { type: 'user', id: req.user!.id },
          )
          imported += 1
        } catch (err) {
          if (err instanceof OkfValidationError) skipped.push(`${path}: ${err.message}`)
          else throw err
        }
      }

      const unmatchedShares: string[] = []
      for (const share of manifest.shares ?? []) {
        if (share.granteeType === 'user' && share.email) {
          const grantee = (
            await db.select().from(users).where(eq(users.email, share.email.toLowerCase()))
          )[0]
          if (grantee && grantee.status === 'active' && grantee.id !== req.user!.id) {
            await db.insert(vaultShares).values({
              vaultId: vault!.id,
              granteeType: 'user',
              granteeId: grantee.id,
              permission: share.permission,
            })
            continue
          }
        }
        unmatchedShares.push(
          share.granteeType === 'user'
            ? (share.email ?? 'unknown user')
            : `team: ${share.teamName ?? 'unknown'}`,
        )
      }

      return { vaultId: vault!.id, imported, skipped, unmatchedShares }
    })

    authed.get('/admin/backup', async (req, reply) => {
      if (req.user!.role !== 'admin') return reply.code(403).send({ error: 'admin required' })
      const zip = await buildInstanceBackup()
      await logSecurityEvent({ type: 'instance_backup_created', actorUserId: req.user!.id })
      return reply
        .header('content-type', 'application/zip')
        .header('content-disposition', 'attachment; filename="chapters-backup.zip"')
        .send(zip)
    })
  })
}

import AdmZip from 'adm-zip'
import { sql } from 'drizzle-orm'
import { db } from '../db/client.js'
import {
  instanceState,
  mcpConnections,
  notifications,
  securityEvents,
  teamMemberships,
  teams,
  users,
  vaults,
  vaultShares,
} from '../db/schema.js'
import { createNote, splitPath } from '../notes/store.js'
import { parseNote, OkfValidationError } from '../notes/okf.js'

export interface RestoreResult {
  users: number
  teams: number
  teamMemberships: number
  vaults: number
  vaultShares: number
  mcpConnections: number
  securityEvents: number
  notifications: number
  notesImported: number
  notesSkipped: string[]
}

/** Restore refuses to run against anything but a genuinely empty instance. */
export async function isInstanceEmpty(): Promise<boolean> {
  const [row] = await db.select({ count: sql<number>`count(*)::int` }).from(users)
  return (row?.count ?? 0) === 0
}

// Produced by buildInstanceBackup()'s own db.select().from(table) calls,
// so structurally these match each table's insert shape once JSON's
// stringified dates are converted back (withDates, below).
interface AccountDump {
  users: Array<typeof users.$inferInsert>
  teams: Array<typeof teams.$inferInsert>
  teamMemberships: Array<typeof teamMemberships.$inferInsert>
  vaults: Array<typeof vaults.$inferInsert>
  vaultShares: Array<typeof vaultShares.$inferInsert>
  mcpConnections: Array<typeof mcpConnections.$inferInsert>
  securityEvents: Array<typeof securityEvents.$inferInsert>
  notifications: Array<typeof notifications.$inferInsert>
}

/** JSON has no Date type — restore every table's timestamp columns back to real Dates. */
function withDates<T extends object>(row: T, fields: (keyof T)[]): T {
  const copy = { ...row }
  for (const field of fields) {
    if (copy[field] != null) copy[field] = new Date(copy[field] as string) as T[typeof field]
  }
  return copy
}

/**
 * Restores a full-instance backup zip (spec 7's "Full-instance admin
 * backup") onto a fresh instance. IDs are preserved from the original
 * dump, not regenerated — this is a restore, not an import; foreign
 * keys across the dump stay intact automatically. Account-layer tables
 * restore inside one transaction; notes restore afterward, per-note
 * best-effort through the same shared OKF-validation write path every
 * other write uses (no restore-specific bypass).
 */
export async function restoreBackup(zipBuffer: Buffer): Promise<RestoreResult> {
  const zip = new AdmZip(zipBuffer)
  const dumpEntry = zip.getEntry('account-dump.json')
  if (!dumpEntry) throw new Error('account-dump.json missing — not a full-instance backup')
  const dump = JSON.parse(dumpEntry.getData().toString('utf8')) as AccountDump

  await db.transaction(async (tx) => {
    if (dump.users.length > 0) {
      await tx.insert(users).values(
        dump.users.map((u) => withDates(u, ['emailVerifiedAt', 'mfaEnabledAt', 'createdAt'])),
      )
    }
    if (dump.teams.length > 0) {
      await tx.insert(teams).values(dump.teams.map((t) => withDates(t, ['createdAt'])))
    }
    if (dump.teamMemberships.length > 0) {
      await tx
        .insert(teamMemberships)
        .values(dump.teamMemberships.map((m) => withDates(m, ['createdAt'])))
    }
    if (dump.vaults.length > 0) {
      await tx.insert(vaults).values(dump.vaults.map((v) => withDates(v, ['createdAt'])))
    }
    if (dump.vaultShares.length > 0) {
      await tx.insert(vaultShares).values(dump.vaultShares.map((s) => withDates(s, ['createdAt'])))
    }
    if (dump.mcpConnections.length > 0) {
      await tx.insert(mcpConnections).values(
        dump.mcpConnections.map((c) =>
          withDates(c, ['expiresAt', 'revokedAt', 'lastUsedAt', 'createdAt']),
        ),
      )
    }
    if (dump.securityEvents.length > 0) {
      await tx
        .insert(securityEvents)
        .values(dump.securityEvents.map((e) => withDates(e, ['createdAt'])))
    }
    if (dump.notifications.length > 0) {
      await tx
        .insert(notifications)
        .values(dump.notifications.map((n) => withDates(n, ['readAt', 'createdAt'])))
    }
    // A fresh instance restoring already-approved users has no reason to
    // repeat the one-time setup-token flow.
    if (dump.users.length > 0) {
      await tx
        .insert(instanceState)
        .values({ setupCompletedAt: new Date() })
        .onConflictDoUpdate({
          target: instanceState.id,
          set: { setupCompletedAt: new Date(), setupTokenHash: null },
        })
    }
  })

  let notesImported = 0
  const notesSkipped: string[] = []
  for (const entry of zip.getEntries()) {
    const match = /^vaults\/([0-9a-f-]+)\/(.+)\.md$/.exec(entry.entryName)
    if (!match) continue
    const [, vaultId, path] = match
    try {
      const { type, name } = splitPath(path!)
      const parsed = parseNote(entry.getData().toString('utf8'))
      const owner = dump.vaults.find((v) => v.id === vaultId)?.ownerId as string | undefined
      await createNote(
        vaultId!,
        { type, name, frontmatter: parsed.frontmatter, body: parsed.body },
        { type: 'user', id: owner },
      )
      notesImported += 1
    } catch (err) {
      if (err instanceof OkfValidationError) notesSkipped.push(`${vaultId}/${path}: ${err.message}`)
      else throw err
    }
  }

  return {
    users: dump.users.length,
    teams: dump.teams.length,
    teamMemberships: dump.teamMemberships.length,
    vaults: dump.vaults.length,
    vaultShares: dump.vaultShares.length,
    mcpConnections: dump.mcpConnections.length,
    securityEvents: dump.securityEvents.length,
    notifications: dump.notifications.length,
    notesImported,
    notesSkipped,
  }
}

import AdmZip from 'adm-zip'
import { eq, inArray } from 'drizzle-orm'
import { db } from '../db/client.js'
import {
  mcpConnections,
  notifications,
  securityEvents,
  teamMemberships,
  teams,
  users,
  vaults,
  vaultShares,
} from '../db/schema.js'
import { listNotes, readNote } from '../notes/store.js'
import { serializeNote, type Frontmatter } from '../notes/okf.js'

export interface ShareManifestEntry {
  granteeType: 'user' | 'team'
  email?: string
  teamName?: string
  permission: 'read' | 'edit'
}

export interface VaultManifest {
  name: string
  mergeable: boolean
  shares: ShareManifestEntry[]
}

/** Builds a vault's manifest: instance metadata, kept out of the note files. */
export async function buildManifest(vaultId: string): Promise<VaultManifest | null> {
  const vault = (await db.select().from(vaults).where(eq(vaults.id, vaultId)))[0]
  if (!vault) return null
  const shares = await db.select().from(vaultShares).where(eq(vaultShares.vaultId, vaultId))
  const userIds = shares.filter((s) => s.granteeType === 'user').map((s) => s.granteeId)
  const teamIds = shares.filter((s) => s.granteeType === 'team').map((s) => s.granteeId)
  const userRows = userIds.length
    ? await db.select({ id: users.id, email: users.email }).from(users).where(inArray(users.id, userIds))
    : []
  const teamRows = teamIds.length
    ? await db.select({ id: teams.id, name: teams.name }).from(teams).where(inArray(teams.id, teamIds))
    : []
  const emailById = new Map(userRows.map((u) => [u.id, u.email]))
  const teamNameById = new Map(teamRows.map((t) => [t.id, t.name]))
  return {
    name: vault.name,
    mergeable: vault.mergeable,
    shares: shares.map((s) => ({
      granteeType: s.granteeType,
      email: s.granteeType === 'user' ? emailById.get(s.granteeId) : undefined,
      teamName: s.granteeType === 'team' ? teamNameById.get(s.granteeId) : undefined,
      permission: s.permission,
    })),
  }
}

/** Adds a vault's OKF tree + manifest to a zip under the given prefix. */
export async function addVaultToZip(zip: AdmZip, vaultId: string, prefix = ''): Promise<void> {
  const manifest = await buildManifest(vaultId)
  if (!manifest) return
  const rows = await listNotes(vaultId)
  for (const row of rows) {
    const note = await readNote(vaultId, row.path)
    if (!note) continue
    zip.addFile(
      `${prefix}${row.path}.md`,
      Buffer.from(
        serializeNote({ frontmatter: note.frontmatter as Frontmatter, body: note.body }),
        'utf8',
      ),
    )
  }
  zip.addFile(`${prefix}manifest.json`, Buffer.from(JSON.stringify(manifest, null, 2), 'utf8'))
}

export async function buildVaultZip(vaultId: string): Promise<Buffer> {
  const zip = new AdmZip()
  await addVaultToZip(zip, vaultId)
  return zip.toBuffer()
}

/** Full-instance admin backup: every vault bundle + the account layer. */
export async function buildInstanceBackup(): Promise<Buffer> {
  const zip = new AdmZip()
  const allVaults = await db.select({ id: vaults.id }).from(vaults)
  for (const vault of allVaults) {
    await addVaultToZip(zip, vault.id, `vaults/${vault.id}/`)
  }
  const dump = {
    users: await db.select().from(users),
    teams: await db.select().from(teams),
    teamMemberships: await db.select().from(teamMemberships),
    vaults: await db.select().from(vaults),
    vaultShares: await db.select().from(vaultShares),
    // Hashed tokens only — raw secrets are never recoverable (spec 1).
    mcpConnections: await db.select().from(mcpConnections),
    securityEvents: await db.select().from(securityEvents),
    notifications: await db.select().from(notifications),
  }
  zip.addFile('account-dump.json', Buffer.from(JSON.stringify(dump, null, 2), 'utf8'))
  return zip.toBuffer()
}

import { resolve } from 'node:path'
import type { FastifyInstance } from 'fastify'
import { and, eq, inArray } from 'drizzle-orm'
import { db } from '../db/client.js'
import {
  repositories,
  repositoryGraphPreferences,
  repositoryShares,
  teamMemberships,
  teams,
  users,
} from '../db/schema.js'
import { config } from '../config.js'
import { logSecurityEvent } from '../auth/security-events.js'
import { encryptCredential } from './credentials.js'
import { generateToken } from '../auth/tokens.js'
import { listAccessibleRepositories, resolveRepositoryAccess } from './permissions.js'
import { createSyncToken, listSyncTokens, revokeSyncToken } from './sync-tokens.js'
import { listRepositoryFiles } from './store.js'
import { buildGraph, type GraphFilters } from '../graph/assemble.js'
import { searchNotes } from '../search/search.js'

function parseGraphFilters(q: {
  types?: string
  tags?: string
  since?: string
  until?: string
}): GraphFilters {
  return {
    types: q.types ? q.types.split(',').filter(Boolean) : undefined,
    tags: q.tags ? q.tags.split(',').filter(Boolean) : undefined,
    since: q.since,
    until: q.until,
  }
}

async function requireOwner(userId: string, repositoryId: string): Promise<boolean> {
  return (await resolveRepositoryAccess(userId, repositoryId)) === 'owner'
}

function repositoryView(repo: typeof repositories.$inferSelect) {
  return {
    id: repo.id,
    name: repo.name,
    ownerId: repo.ownerId,
    ingestionMethod: repo.ingestionMethod,
    gitUrl: repo.gitUrl,
    localPath: repo.localPath,
    mergeable: repo.mergeable,
    syncStatus: repo.syncStatus,
    lastSyncedAt: repo.lastSyncedAt,
    lastSyncError: repo.lastSyncError,
    createdAt: repo.createdAt,
  }
}

function isWithinLocalReposRoot(candidate: string): boolean {
  const root = resolve(config.localReposRoot)
  const resolved = resolve(root, candidate)
  return resolved === root || resolved.startsWith(root + '/')
}

export function repositoryRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  app.post<{
    Body: {
      name: string
      ingestionMethod: 'git' | 'local_path' | 'agent_push'
      gitUrl?: string
      gitCredential?: string
      localPath?: string
    }
  }>(
    '/repositories',
    {
      schema: {
        body: {
          type: 'object',
          required: ['name', 'ingestionMethod'],
          properties: {
            name: { type: 'string', minLength: 1, maxLength: 200 },
            ingestionMethod: { enum: ['git', 'local_path', 'agent_push'] },
            gitUrl: { type: 'string', minLength: 1 },
            gitCredential: { type: 'string', minLength: 1 },
            localPath: { type: 'string', minLength: 1 },
          },
        },
      },
    },
    async (req, reply) => {
      const { name, ingestionMethod, gitUrl, gitCredential, localPath } = req.body

      if (ingestionMethod === 'git' && !gitUrl) {
        return reply.code(400).send({ error: 'gitUrl is required for the git ingestion method' })
      }
      if (ingestionMethod === 'local_path') {
        if (!localPath) {
          return reply.code(400).send({ error: 'localPath is required for the local_path ingestion method' })
        }
        if (!isWithinLocalReposRoot(localPath)) {
          return reply.code(400).send({ error: 'localPath must resolve under the configured local repos root' })
        }
      }

      let gitCredentialEncrypted: string | undefined
      if (gitCredential) {
        try {
          gitCredentialEncrypted = encryptCredential(gitCredential)
        } catch (err) {
          return reply.code(400).send({ error: (err as Error).message })
        }
      }

      const [repo] = await db
        .insert(repositories)
        .values({
          name,
          ownerId: req.user!.id,
          ingestionMethod,
          gitUrl: ingestionMethod === 'git' ? gitUrl : undefined,
          gitCredentialEncrypted,
          localPath: ingestionMethod === 'local_path' ? resolve(config.localReposRoot, localPath!) : undefined,
        })
        .returning()

      // Never echo the credential back — created-once, write-only from here.
      return repositoryView(repo!)
    },
  )

  app.get('/repositories', async (req) => listAccessibleRepositories(req.user!.id))

  app.get<{ Params: { id: string } }>('/repositories/:id/access', async (req, reply) => {
    const access = await resolveRepositoryAccess(req.user!.id, req.params.id)
    if (!access) return reply.code(404).send({ error: 'not found' })
    return { access }
  })

  app.patch<{ Params: { id: string }; Body: { name?: string; mergeable?: boolean } }>(
    '/repositories/:id',
    {
      schema: {
        body: {
          type: 'object',
          properties: {
            name: { type: 'string', minLength: 1, maxLength: 200 },
            mergeable: { type: 'boolean' },
          },
        },
      },
    },
    async (req, reply) => {
      if (!(await requireOwner(req.user!.id, req.params.id))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const [repo] = await db
        .update(repositories)
        .set(req.body)
        .where(eq(repositories.id, req.params.id))
        .returning()
      return repositoryView(repo!)
    },
  )

  app.delete<{ Params: { id: string } }>('/repositories/:id', async (req, reply) => {
    if (!(await requireOwner(req.user!.id, req.params.id))) {
      return reply.code(404).send({ error: 'not found' })
    }
    await db.delete(repositories).where(eq(repositories.id, req.params.id))
    return { status: 'deleted' }
  })

  app.post<{
    Params: { id: string }
    Body: { granteeType: 'user' | 'team'; granteeId: string }
  }>(
    '/repositories/:id/shares',
    {
      schema: {
        body: {
          type: 'object',
          required: ['granteeType', 'granteeId'],
          properties: {
            granteeType: { enum: ['user', 'team'] },
            granteeId: { type: 'string', format: 'uuid' },
          },
        },
      },
    },
    async (req, reply) => {
      const repositoryId = req.params.id
      if (!(await requireOwner(req.user!.id, repositoryId))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const { granteeType, granteeId } = req.body
      if (granteeType === 'user') {
        const grantee = (await db.select().from(users).where(eq(users.id, granteeId)))[0]
        if (!grantee || grantee.status !== 'active') {
          return reply.code(400).send({ error: 'grantee must be an active user' })
        }
      } else {
        const team = (await db.select().from(teams).where(eq(teams.id, granteeId)))[0]
        if (!team) return reply.code(400).send({ error: 'team not found' })
      }
      const [share] = await db
        .insert(repositoryShares)
        .values({ repositoryId, granteeType, granteeId })
        .onConflictDoNothing()
        .returning()
      await logSecurityEvent({
        type: 'repository_share_created',
        actorUserId: req.user!.id,
        detail: { repositoryId, granteeType, granteeId },
      })
      return share ?? { status: 'already_shared' }
    },
  )

  app.get<{ Params: { id: string } }>('/repositories/:id/shares', async (req, reply) => {
    const repositoryId = req.params.id
    if (!(await requireOwner(req.user!.id, repositoryId))) {
      return reply.code(404).send({ error: 'not found' })
    }
    const shares = await db
      .select()
      .from(repositoryShares)
      .where(eq(repositoryShares.repositoryId, repositoryId))
    const teamIds = shares.filter((s) => s.granteeType === 'team').map((s) => s.granteeId)
    const members = teamIds.length
      ? await db
          .select({
            teamId: teamMemberships.teamId,
            userId: teamMemberships.userId,
            email: users.email,
          })
          .from(teamMemberships)
          .innerJoin(users, eq(users.id, teamMemberships.userId))
          .where(inArray(teamMemberships.teamId, teamIds))
      : []
    return shares.map((s) => ({
      ...s,
      members: s.granteeType === 'team' ? members.filter((m) => m.teamId === s.granteeId) : undefined,
    }))
  })

  app.delete<{ Params: { id: string; shareId: string } }>(
    '/repositories/:id/shares/:shareId',
    async (req, reply) => {
      const repositoryId = req.params.id
      if (!(await requireOwner(req.user!.id, repositoryId))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const [share] = await db
        .delete(repositoryShares)
        .where(
          and(eq(repositoryShares.id, req.params.shareId), eq(repositoryShares.repositoryId, repositoryId)),
        )
        .returning()
      if (!share) return reply.code(404).send({ error: 'share not found' })
      await logSecurityEvent({
        type: 'repository_share_revoked',
        actorUserId: req.user!.id,
        detail: { repositoryId, shareId: share.id },
      })
      return { status: 'revoked' }
    },
  )

  app.get<{
    Params: { id: string }
    Querystring: { types?: string; tags?: string; since?: string; until?: string }
  }>('/repositories/:id/graph', async (req, reply) => {
    const access = await resolveRepositoryAccess(req.user!.id, req.params.id)
    if (!access) return reply.code(404).send({ error: 'not found' })
    return buildGraph(
      { vaultIds: [], repositoryIds: [req.params.id] },
      parseGraphFilters(req.query),
    )
  })

  app.get<{ Params: { id: string }; Querystring: { q: string; limit?: number } }>(
    '/repositories/:id/search',
    {
      schema: {
        querystring: {
          type: 'object',
          required: ['q'],
          properties: {
            q: { type: 'string', minLength: 1, maxLength: 500 },
            limit: { type: 'integer', minimum: 1, maximum: 100, default: 20 },
          },
        },
      },
    },
    async (req, reply) => {
      const access = await resolveRepositoryAccess(req.user!.id, req.params.id)
      if (!access) return reply.code(404).send({ error: 'not found' })
      return searchNotes({ vaultIds: [], repositoryIds: [req.params.id] }, req.query.q, req.query.limit)
    },
  )

  app.get<{ Params: { id: string } }>('/repositories/:id/files', async (req, reply) => {
    const access = await resolveRepositoryAccess(req.user!.id, req.params.id)
    if (!access) return reply.code(404).send({ error: 'not found' })
    return listRepositoryFiles(req.params.id)
  })

  app.post<{ Params: { id: string } }>('/repositories/:id/webhook-secret', async (req, reply) => {
    if (!(await requireOwner(req.user!.id, req.params.id))) {
      return reply.code(404).send({ error: 'not found' })
    }
    const repo = (await db.select().from(repositories).where(eq(repositories.id, req.params.id)))[0]!
    if (repo.ingestionMethod !== 'git') {
      return reply.code(400).send({ error: 'webhooks only apply to git-sourced repositories' })
    }
    const secret = generateToken()
    await db
      .update(repositories)
      .set({ webhookSecretEncrypted: encryptCredential(secret) })
      .where(eq(repositories.id, req.params.id))
    // Shown exactly once — configure it on the git host's webhook settings now.
    return { secret, webhookPath: `/repositories/${req.params.id}/webhook` }
  })

  app.post<{ Params: { id: string } }>('/repositories/:id/sync-tokens', async (req, reply) => {
    if (!(await requireOwner(req.user!.id, req.params.id))) {
      return reply.code(404).send({ error: 'not found' })
    }
    const token = await createSyncToken(req.params.id)
    // Shown exactly once, same pattern as MCP connection tokens.
    return { token }
  })

  app.get<{ Params: { id: string } }>('/repositories/:id/sync-tokens', async (req, reply) => {
    if (!(await requireOwner(req.user!.id, req.params.id))) {
      return reply.code(404).send({ error: 'not found' })
    }
    return listSyncTokens(req.params.id)
  })

  app.post<{ Params: { id: string; tokenId: string } }>(
    '/repositories/:id/sync-tokens/:tokenId/revoke',
    async (req, reply) => {
      if (!(await requireOwner(req.user!.id, req.params.id))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const revoked = await revokeSyncToken(req.params.id, req.params.tokenId)
      if (!revoked) return reply.code(404).send({ error: 'token not found' })
      return { status: 'revoked' }
    },
  )

  app.put<{ Params: { id: string }; Body: { include: boolean } }>(
    '/repositories/:id/graph-preference',
    {
      schema: {
        body: {
          type: 'object',
          required: ['include'],
          properties: { include: { type: 'boolean' } },
        },
      },
    },
    async (req, reply) => {
      // Requires current access — the toggle must not probe repository IDs.
      const access = await resolveRepositoryAccess(req.user!.id, req.params.id)
      if (!access) return reply.code(404).send({ error: 'not found' })
      await db
        .insert(repositoryGraphPreferences)
        .values({ userId: req.user!.id, repositoryId: req.params.id, include: req.body.include })
        .onConflictDoUpdate({
          target: [repositoryGraphPreferences.userId, repositoryGraphPreferences.repositoryId],
          set: { include: req.body.include },
        })
      return { include: req.body.include }
    },
  )
}

import { createHmac, timingSafeEqual } from 'node:crypto'
import type { FastifyInstance, FastifyRequest } from 'fastify'
import { eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { repositories } from '../db/schema.js'
import { decryptCredential } from './credentials.js'
import { syncGitRepository } from './git-sync.js'
import { logSecurityEvent } from '../auth/security-events.js'

declare module 'fastify' {
  interface FastifyRequest {
    rawBody?: Buffer
  }
}

function verifySignature(rawBody: Buffer, secret: string, header: string): boolean {
  const expected = `sha256=${createHmac('sha256', secret).update(rawBody).digest('hex')}`
  const expectedBuf = Buffer.from(expected)
  const headerBuf = Buffer.from(header)
  return expectedBuf.length === headerBuf.length && timingSafeEqual(expectedBuf, headerBuf)
}

/**
 * GitHub/GitLab push-event receiver (spec 8): genuinely real-time
 * freshness for reachable self-hosted instances. Scoped to its own
 * plugin context so the raw-body content-type parser doesn't affect
 * JSON parsing anywhere else in the app.
 */
export function repositoryWebhookRoutes(app: FastifyInstance) {
  app.register(async (instance) => {
    instance.addContentTypeParser(
      'application/json',
      { parseAs: 'buffer' },
      (req: FastifyRequest, body: Buffer, done) => {
        req.rawBody = body
        try {
          done(null, body.length ? JSON.parse(body.toString('utf8')) : {})
        } catch (err) {
          done(err as Error, undefined)
        }
      },
    )

    instance.post<{ Params: { id: string } }>('/repositories/:id/webhook', async (req, reply) => {
      const repo = (
        await db.select().from(repositories).where(eq(repositories.id, req.params.id))
      )[0]
      if (!repo || !repo.webhookSecretEncrypted) {
        return reply.code(404).send({ error: 'not found' })
      }
      const signature = req.headers['x-hub-signature-256']
      if (typeof signature !== 'string' || !req.rawBody) {
        await logSecurityEvent({ type: 'webhook_rejected', ip: req.ip, detail: { repositoryId: repo.id } })
        return reply.code(401).send({ error: 'missing signature' })
      }
      const secret = decryptCredential(repo.webhookSecretEncrypted)
      if (!verifySignature(req.rawBody, secret, signature)) {
        await logSecurityEvent({ type: 'webhook_rejected', ip: req.ip, detail: { repositoryId: repo.id } })
        return reply.code(401).send({ error: 'invalid signature' })
      }

      await db
        .update(repositories)
        .set({ lastWebhookAt: new Date() })
        .where(eq(repositories.id, repo.id))

      // Fire-and-forget: the webhook response returns immediately, sync runs async.
      void syncGitRepository(repo.id).catch((err) => {
        console.error(`webhook-triggered sync failed for repository ${repo.id}:`, err)
      })
      return { status: 'accepted' }
    })
  })
}

import type { FastifyInstance } from 'fastify'
import { eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { repositories } from '../db/schema.js'
import { resolveSyncToken } from './sync-tokens.js'
import { syncRepositoryFiles } from './store.js'

interface PushBody {
  files: Array<{ path: string; content: string }>
  currentPaths: string[]
}

/**
 * Agent/CLI push ingestion (spec 8): a client that already has the
 * repository checked out locally sends changed files directly — no
 * clone, no watcher, the closest analog to how Graphify itself
 * operates (parse where the code already is).
 */
export function repositoryPushRoutes(app: FastifyInstance) {
  app.post<{ Body: PushBody }>(
    '/repositories/sync',
    {
      schema: {
        body: {
          type: 'object',
          required: ['files', 'currentPaths'],
          properties: {
            files: {
              type: 'array',
              items: {
                type: 'object',
                required: ['path', 'content'],
                properties: {
                  path: { type: 'string', minLength: 1 },
                  content: { type: 'string' },
                },
              },
            },
            currentPaths: { type: 'array', items: { type: 'string' } },
          },
        },
      },
    },
    async (req, reply) => {
      const header = req.headers.authorization
      const token = header?.startsWith('Bearer ') ? header.slice(7) : null
      const auth = token ? await resolveSyncToken(token) : null
      if (!auth) return reply.code(401).send({ error: 'invalid or revoked sync token' })

      const result = await syncRepositoryFiles(auth.repositoryId, req.body.files, req.body.currentPaths)
      await db
        .update(repositories)
        .set({ syncStatus: 'idle', lastSyncedAt: new Date(), lastSyncError: null })
        .where(eq(repositories.id, auth.repositoryId))
      return result
    },
  )
}

import { readFile, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { randomBytes } from 'node:crypto'
import { simpleGit } from 'simple-git'
import { eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { repositories } from '../db/schema.js'
import { decryptCredential } from './credentials.js'
import { listFilesRecursive } from './fs-scan.js'
import { syncRepositoryFiles, type FileUpdate } from './store.js'

const IGNORED = /(^|\/)\.git(\/|$)/

/** Injects a decrypted credential as basic-auth username — the common convention for PATs. */
function authenticatedUrl(gitUrl: string, credential: string | null): string {
  if (!credential) return gitUrl
  const url = new URL(gitUrl)
  url.username = credential
  return url.toString()
}

/**
 * Git URL ingestion (spec 8): a fresh shallow clone (depth 1, no
 * history) into a scratch temp directory on every sync — simpler and
 * more robust than reusing/fetching into a persistent working copy, at
 * the cost of a full re-clone each time. The clone is discarded after
 * its tree is read; only the extracted file content is durable.
 */
export async function syncGitRepository(repositoryId: string): Promise<void> {
  const repo = (await db.select().from(repositories).where(eq(repositories.id, repositoryId)))[0]
  if (!repo || repo.ingestionMethod !== 'git' || !repo.gitUrl) return

  await db
    .update(repositories)
    .set({ syncStatus: 'syncing' })
    .where(eq(repositories.id, repositoryId))

  const workDir = join(tmpdir(), 'chapters-repo-clones', randomBytes(8).toString('hex'))
  try {
    const credential = repo.gitCredentialEncrypted
      ? decryptCredential(repo.gitCredentialEncrypted)
      : null
    const cloneUrl = authenticatedUrl(repo.gitUrl, credential)
    await simpleGit().clone(cloneUrl, workDir, ['--depth', '1'])

    const currentPaths = await listFilesRecursive(workDir, IGNORED)
    const files: FileUpdate[] = []
    for (const path of currentPaths) {
      files.push({ path, content: await readFile(join(workDir, path), 'utf8') })
    }
    await syncRepositoryFiles(repositoryId, files, currentPaths)

    await db
      .update(repositories)
      .set({ syncStatus: 'idle', lastSyncedAt: new Date(), lastSyncError: null })
      .where(eq(repositories.id, repositoryId))
  } catch (err) {
    await db
      .update(repositories)
      .set({ syncStatus: 'error', lastSyncError: (err as Error).message })
      .where(eq(repositories.id, repositoryId))
    throw err
  } finally {
    await rm(workDir, { recursive: true, force: true })
  }
}

import { readFile } from 'node:fs/promises'
import { join, relative } from 'node:path'
import chokidar from 'chokidar'
import { syncRepositoryFiles, type FileUpdate } from './store.js'
import { listFilesRecursive } from './fs-scan.js'

// ponytail: hardcoded ignore list, not full .gitignore parsing — covers
// the overwhelming common case (vendored deps, git internals) cheaply.
export const IGNORED = /(^|\/)(\.git|node_modules)(\/|$)/

const DEBOUNCE_MS = 300

/** Real-time local-path ingestion (spec 8). Returns a stop() to close the watcher. */
export function startWatching(repositoryId: string, localPath: string): () => void {
  let timer: ReturnType<typeof setTimeout> | null = null

  // ponytail: rescans + rereads every file on any change (syncRepositoryFiles's
  // hash check filters out the no-ops); switch to chokidar's per-event paths
  // if profiling shows this matters for very large local trees.
  const runSync = () => {
    void (async () => {
      const currentPaths = await listFilesRecursive(localPath, IGNORED)
      const files: FileUpdate[] = []
      for (const path of currentPaths) {
        try {
          files.push({ path, content: await readFile(join(localPath, path), 'utf8') })
        } catch {
          // File vanished between listing and reading (rename/delete race) — skip it,
          // the next sync's manifest will reflect reality.
        }
      }
      await syncRepositoryFiles(repositoryId, files, currentPaths)
    })()
  }

  const watcher = chokidar.watch(localPath, {
    ignored: (path) => IGNORED.test(relative(localPath, path)),
    ignoreInitial: false,
  })
  watcher.on('all', () => {
    if (timer) clearTimeout(timer)
    timer = setTimeout(runSync, DEBOUNCE_MS)
  })

  return () => {
    if (timer) clearTimeout(timer)
    void watcher.close()
  }
}

