import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto'
import { config } from '../config.js'

export class EncryptionKeyMissingError extends Error {
  constructor() {
    super(
      'CREDENTIALS_ENCRYPTION_KEY is not configured — required for private repo credentials and webhook secrets',
    )
  }
}

function key(): Buffer {
  if (!config.credentialsEncryptionKey) throw new EncryptionKeyMissingError()
  const buf = Buffer.from(config.credentialsEncryptionKey, 'hex')
  if (buf.length !== 32) {
    throw new Error('CREDENTIALS_ENCRYPTION_KEY must be 32 bytes (64 hex characters)')
  }
  return buf
}

/** AES-256-GCM: authenticated encryption — tampering fails decryption, not just detection. */
export function encryptCredential(plaintext: string): string {
  const iv = randomBytes(12)
  const cipher = createCipheriv('aes-256-gcm', key(), iv)
  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()])
  const authTag = cipher.getAuthTag()
  return [iv.toString('hex'), authTag.toString('hex'), ciphertext.toString('hex')].join(':')
}

export function decryptCredential(blob: string): string {
  const [ivHex, authTagHex, ciphertextHex] = blob.split(':')
  if (!ivHex || !authTagHex || !ciphertextHex) {
    throw new Error('malformed credential blob')
  }
  const decipher = createDecipheriv('aes-256-gcm', key(), Buffer.from(ivHex, 'hex'))
  decipher.setAuthTag(Buffer.from(authTagHex, 'hex'))
  const plaintext = Buffer.concat([
    decipher.update(Buffer.from(ciphertextHex, 'hex')),
    decipher.final(),
  ])
  return plaintext.toString('utf8')
}

import { and, eq, isNull } from 'drizzle-orm'
import { db } from '../db/client.js'
import { repositorySyncTokens } from '../db/schema.js'
import { generateToken, hashToken } from '../auth/tokens.js'

export async function createSyncToken(repositoryId: string): Promise<string> {
  const token = generateToken()
  await db.insert(repositorySyncTokens).values({ repositoryId, tokenHash: hashToken(token) })
  return token
}

/** Live resolution — revoked tokens never resolve, same posture as MCP tokens. */
export async function resolveSyncToken(
  token: string,
): Promise<{ repositoryId: string; tokenId: string } | null> {
  const rows = await db
    .select()
    .from(repositorySyncTokens)
    .where(and(eq(repositorySyncTokens.tokenHash, hashToken(token)), isNull(repositorySyncTokens.revokedAt)))
    .limit(1)
  const row = rows[0]
  if (!row) return null
  await db
    .update(repositorySyncTokens)
    .set({ lastUsedAt: new Date() })
    .where(eq(repositorySyncTokens.id, row.id))
  return { repositoryId: row.repositoryId, tokenId: row.id }
}

export async function revokeSyncToken(repositoryId: string, tokenId: string): Promise<boolean> {
  const updated = await db
    .update(repositorySyncTokens)
    .set({ revokedAt: new Date() })
    .where(
      and(
        eq(repositorySyncTokens.id, tokenId),
        eq(repositorySyncTokens.repositoryId, repositoryId),
        isNull(repositorySyncTokens.revokedAt),
      ),
    )
    .returning({ id: repositorySyncTokens.id })
  return updated.length > 0
}

export async function listSyncTokens(repositoryId: string) {
  return db
    .select({
      id: repositorySyncTokens.id,
      createdAt: repositorySyncTokens.createdAt,
      lastUsedAt: repositorySyncTokens.lastUsedAt,
      revokedAt: repositorySyncTokens.revokedAt,
    })
    .from(repositorySyncTokens)
    .where(eq(repositorySyncTokens.repositoryId, repositoryId))
}

import { createHash } from 'node:crypto'
import { and, eq, notInArray } from 'drizzle-orm'
import { db } from '../db/client.js'
import { repositoryFiles, repositoryFileSymbols } from '../db/schema.js'
import { detectLanguage } from './language.js'
import { scheduleExtraction } from './extraction-queue.js'

export type RepositoryFileRow = typeof repositoryFiles.$inferSelect

export interface FileUpdate {
  path: string
  content: string
  sourceModifiedAt?: Date
}

export interface SyncResult {
  created: number
  updated: number
  deleted: number
  unchanged: number
}

/**
 * The one write path for repository file content (spec 8): every
 * ingestion method funnels through here. `contentHash` is always
 * computed server-side from `content` — never trusted from a caller,
 * since the server is the single source of truth regardless of how the
 * content arrived.
 */
export async function syncRepositoryFiles(
  repositoryId: string,
  changedOrNewFiles: FileUpdate[],
  currentPaths: string[],
): Promise<SyncResult> {
  const existing = await db
    .select({ id: repositoryFiles.id, path: repositoryFiles.path, contentHash: repositoryFiles.contentHash })
    .from(repositoryFiles)
    .where(eq(repositoryFiles.repositoryId, repositoryId))
  const existingByPath = new Map(existing.map((r) => [r.path, r]))

  const result: SyncResult = { created: 0, updated: 0, deleted: 0, unchanged: 0 }
  // Extraction is scheduled only after the whole batch is persisted (below)
  // — starting it per-file would race cross-file import resolution against
  // sibling files in the same batch still being inserted.
  const toExtract: string[] = []

  for (const file of changedOrNewFiles) {
    const contentHash = createHash('sha256').update(file.content).digest('hex')
    const current = existingByPath.get(file.path)
    if (current && current.contentHash === contentHash) {
      result.unchanged += 1
      continue
    }
    const values = {
      repositoryId,
      path: file.path,
      language: detectLanguage(file.path),
      content: file.content,
      contentHash,
      size: Buffer.byteLength(file.content, 'utf8'),
      sourceModifiedAt: file.sourceModifiedAt,
      updatedAt: new Date(),
    }
    if (current) {
      await db.update(repositoryFiles).set(values).where(eq(repositoryFiles.id, current.id))
      toExtract.push(current.id)
      result.updated += 1
    } else {
      const [inserted] = await db.insert(repositoryFiles).values(values).returning({ id: repositoryFiles.id })
      toExtract.push(inserted!.id)
      result.created += 1
    }
  }

  const currentPathSet = new Set(currentPaths)
  const toDelete = existing.filter((r) => !currentPathSet.has(r.path))
  if (toDelete.length > 0) {
    await db.delete(repositoryFiles).where(
      and(
        eq(repositoryFiles.repositoryId, repositoryId),
        notInArray(
          repositoryFiles.path,
          currentPaths.length > 0 ? currentPaths : ['\0-impossible-path-\0'],
        ),
      ),
    )
    result.deleted = toDelete.length
  }

  for (const id of toExtract) scheduleExtraction(id)

  return result
}

export async function getRepositoryFile(
  repositoryId: string,
  path: string,
): Promise<RepositoryFileRow | null> {
  const rows = await db
    .select()
    .from(repositoryFiles)
    .where(and(eq(repositoryFiles.repositoryId, repositoryId), eq(repositoryFiles.path, path)))
  return rows[0] ?? null
}

export async function listRepositoryFiles(
  repositoryId: string,
): Promise<Array<Pick<RepositoryFileRow, 'id' | 'path' | 'language' | 'size' | 'updatedAt'>>> {
  return db
    .select({
      id: repositoryFiles.id,
      path: repositoryFiles.path,
      language: repositoryFiles.language,
      size: repositoryFiles.size,
      updatedAt: repositoryFiles.updatedAt,
    })
    .from(repositoryFiles)
    .where(eq(repositoryFiles.repositoryId, repositoryId))
}

/** Declared top-level symbols for a file — its "outline" (spec 9). */
export async function listFileSymbols(
  fileId: string,
): Promise<Array<Pick<typeof repositoryFileSymbols.$inferSelect, 'name' | 'kind' | 'startLine' | 'endLine'>>> {
  return db
    .select({
      name: repositoryFileSymbols.name,
      kind: repositoryFileSymbols.kind,
      startLine: repositoryFileSymbols.startLine,
      endLine: repositoryFileSymbols.endLine,
    })
    .from(repositoryFileSymbols)
    .where(eq(repositoryFileSymbols.fileId, fileId))
}

import { and, eq, ne } from 'drizzle-orm'
import { db } from '../db/client.js'
import { repositories } from '../db/schema.js'
import { syncGitRepository } from './git-sync.js'

/**
 * Pure decision function (unit-tested directly — the interval loop
 * around it isn't): poll unless a webhook has been seen recently
 * enough that the repository is already staying current on its own.
 */
export function shouldPoll(
  lastWebhookAt: Date | null,
  lastSyncedAt: Date | null,
  now: Date,
  thresholdMs: number,
): boolean {
  if (!lastWebhookAt) return true
  const webhookIsStale = now.getTime() - lastWebhookAt.getTime() > thresholdMs
  if (!webhookIsStale) return false
  // A stale webhook doesn't matter if something else (a manual/agent
  // sync) already caught the repository up more recently than that.
  return !lastSyncedAt || lastSyncedAt < lastWebhookAt
}

/** Fallback freshness for git repositories a webhook can't reach (spec 8). */
export function startPollingScheduler(intervalMs: number, thresholdMs: number): () => void {
  const timer = setInterval(() => {
    void tick(thresholdMs)
  }, intervalMs)
  return () => clearInterval(timer)
}

async function tick(thresholdMs: number): Promise<void> {
  const candidates = await db
    .select()
    .from(repositories)
    .where(and(eq(repositories.ingestionMethod, 'git'), ne(repositories.syncStatus, 'syncing')))

  const now = new Date()
  for (const repo of candidates) {
    if (!shouldPoll(repo.lastWebhookAt, repo.lastSyncedAt, now, thresholdMs)) continue
    try {
      await syncGitRepository(repo.id)
    } catch (err) {
      console.error(`polling sync failed for repository ${repo.id}:`, err)
    }
  }
}

import { eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { repositoryFileImports, repositoryFileSymbols, repositoryFiles } from '../db/schema.js'
import { embedder } from '../search/embeddings.js'
import { recomputeSemanticEdges } from '../search/semantic-edges.js'
import { extractStructure, isSupportedLanguage } from './extraction.js'
import { resolveImportPath } from './import-resolution.js'

// ponytail: in-process serial queue; move to a job table if multi-process
const queue: string[] = []
let running: Promise<void> | null = null

/** Enqueue a repository file for extraction + embedding. Never blocks the caller. */
export function scheduleExtraction(fileId: string): void {
  queue.push(fileId)
  running ??= drain().finally(() => {
    running = null
  })
}

export async function flushExtraction(): Promise<void> {
  while (running) await running
}

async function drain(): Promise<void> {
  while (queue.length > 0) {
    const fileId = queue.shift()!
    try {
      await processFile(fileId)
    } catch (err) {
      console.error(`extraction failed for repository file ${fileId}:`, err)
    }
  }
}

async function processFile(fileId: string): Promise<void> {
  const row = (await db.select().from(repositoryFiles).where(eq(repositoryFiles.id, fileId)))[0]
  if (!row) return

  if (isSupportedLanguage(row.language)) {
    const { imports, symbols } = await extractStructure(row.language, row.content)

    const siblings = await db
      .select({ id: repositoryFiles.id, path: repositoryFiles.path })
      .from(repositoryFiles)
      .where(eq(repositoryFiles.repositoryId, row.repositoryId))
    const pathToId = new Map(siblings.map((s) => [s.path, s.id]))
    const knownPaths = new Set(siblings.map((s) => s.path))

    await db.delete(repositoryFileImports).where(eq(repositoryFileImports.sourceFileId, fileId))
    if (imports.length > 0) {
      const rows = imports.map((targetPath) => {
        const resolved = resolveImportPath(row.path, targetPath, knownPaths)
        return {
          sourceFileId: fileId,
          targetPath,
          resolvedTargetFileId: resolved ? pathToId.get(resolved) : undefined,
        }
      })
      await db.insert(repositoryFileImports).values(rows).onConflictDoNothing()
    }

    await db.delete(repositoryFileSymbols).where(eq(repositoryFileSymbols.fileId, fileId))
    if (symbols.length > 0) {
      await db.insert(repositoryFileSymbols).values(
        symbols.map((s) => ({
          fileId,
          name: s.name,
          kind: s.kind,
          startLine: s.startLine,
          endLine: s.endLine,
        })),
      )
    }
  }

  const [embedding] = await embedder.embed([`${row.path}\n${row.content}`])
  await db.update(repositoryFiles).set({ embedding }).where(eq(repositoryFiles.id, fileId))
  await recomputeSemanticEdges('code', fileId, embedding!)
}

import { readFile } from 'node:fs/promises'
import { createRequire } from 'node:module'
import { dirname, join } from 'node:path'
import { Parser, Language, Query } from 'web-tree-sitter'

const require = createRequire(import.meta.url)

export type SymbolKind = 'function' | 'class' | 'interface' | 'type'

export interface ExtractedSymbol {
  name: string
  kind: SymbolKind
  startLine: number
  endLine: number
}

export interface ExtractionResult {
  imports: string[]
  symbols: ExtractedSymbol[]
}

type SupportedLanguage = 'typescript' | 'javascript' | 'python' | 'go'

const SUPPORTED = new Set<SupportedLanguage>(['typescript', 'javascript', 'python', 'go'])

export function isSupportedLanguage(language: string | null): language is SupportedLanguage {
  return language !== null && SUPPORTED.has(language as SupportedLanguage)
}

const wasmPath = (pkg: string, file: string): string =>
  join(dirname(require.resolve(`${pkg}/package.json`)), file)

interface GrammarConfig {
  wasm: string
  importQuery: string
  symbolQuery: string
}

const GRAMMARS: Record<SupportedLanguage, GrammarConfig> = {
  typescript: {
    wasm: wasmPath('tree-sitter-typescript', 'tree-sitter-typescript.wasm'),
    importQuery: `(import_statement source: (string (string_fragment) @src))`,
    symbolQuery: `
      [
        (function_declaration name: (identifier) @name) @decl.function
        (class_declaration name: (type_identifier) @name) @decl.class
        (interface_declaration name: (type_identifier) @name) @decl.interface
        (type_alias_declaration name: (type_identifier) @name) @decl.type
      ]
    `,
  },
  javascript: {
    wasm: wasmPath('tree-sitter-javascript', 'tree-sitter-javascript.wasm'),
    importQuery: `(import_statement source: (string (string_fragment) @src))`,
    symbolQuery: `
      [
        (function_declaration name: (identifier) @name) @decl.function
        (class_declaration name: (identifier) @name) @decl.class
      ]
    `,
  },
  python: {
    wasm: wasmPath('tree-sitter-python', 'tree-sitter-python.wasm'),
    importQuery: `
      [
        (import_statement name: (dotted_name) @src)
        (import_from_statement module_name: (dotted_name) @src)
        (import_from_statement module_name: (relative_import) @src)
      ]
    `,
    symbolQuery: `
      [
        (function_definition name: (identifier) @name) @decl.function
        (class_definition name: (identifier) @name) @decl.class
      ]
    `,
  },
  go: {
    wasm: wasmPath('tree-sitter-go', 'tree-sitter-go.wasm'),
    importQuery: `(import_spec path: (interpreted_string_literal (interpreted_string_literal_content) @src))`,
    symbolQuery: `
      [
        (function_declaration name: (identifier) @name) @decl.function
        (type_declaration (type_spec name: (type_identifier) @name)) @decl.type
      ]
    `,
  },
}

const SYMBOL_KIND_BY_CAPTURE: Record<string, SymbolKind> = {
  'decl.function': 'function',
  'decl.class': 'class',
  'decl.interface': 'interface',
  'decl.type': 'type',
}

let initPromise: Promise<void> | null = null
const languageCache = new Map<SupportedLanguage, Language>()

async function loadLanguage(language: SupportedLanguage): Promise<Language> {
  initPromise ??= Parser.init()
  await initPromise
  let lang = languageCache.get(language)
  if (!lang) {
    const wasmBytes = await readFile(GRAMMARS[language].wasm)
    lang = await Language.load(wasmBytes)
    languageCache.set(language, lang)
  }
  return lang
}

/** Tree-sitter, file-level extraction (spec 9): import edges + cheap top-level "contains" symbols. */
export async function extractStructure(language: string, content: string): Promise<ExtractionResult> {
  if (!isSupportedLanguage(language)) {
    throw new Error(`unsupported language for extraction: ${language}`)
  }
  const config = GRAMMARS[language]
  const lang = await loadLanguage(language)
  const parser = new Parser()
  parser.setLanguage(lang)
  const tree = parser.parse(content)
  if (!tree) return { imports: [], symbols: [] }

  const imports: string[] = []
  for (const match of new Query(lang, config.importQuery).matches(tree.rootNode)) {
    for (const capture of match.captures) imports.push(capture.node.text)
  }

  const symbols: ExtractedSymbol[] = []
  for (const match of new Query(lang, config.symbolQuery).matches(tree.rootNode)) {
    const nameCapture = match.captures.find((c) => c.name === 'name')
    const declCapture = match.captures.find((c) => c.name in SYMBOL_KIND_BY_CAPTURE)
    if (!nameCapture || !declCapture) continue
    symbols.push({
      name: nameCapture.node.text,
      kind: SYMBOL_KIND_BY_CAPTURE[declCapture.name]!,
      startLine: declCapture.node.startPosition.row + 1,
      endLine: declCapture.node.endPosition.row + 1,
    })
  }

  return { imports, symbols }
}

import { readdir } from 'node:fs/promises'
import { join, relative } from 'node:path'

/** Every file path (relative to `root`) not matching `ignore`. Shared by local-path and git-clone ingestion. */
export async function listFilesRecursive(root: string, ignore: RegExp): Promise<string[]> {
  const entries = await readdir(root, { recursive: true, withFileTypes: true })
  return entries
    .filter((e) => e.isFile())
    .map((e) => relative(root, join(e.parentPath, e.name)))
    .filter((p) => !ignore.test(p))
}

import { posix } from 'node:path'

const CANDIDATE_EXTENSIONS = ['.ts', '.tsx', '.js', '.jsx', '.py', '.go']

/**
 * Best-effort resolution of a raw import specifier to a file that
 * actually exists in this repository (spec 9: "relative and common
 * alias patterns", not exhaustive module-resolution semantics).
 * Non-relative specifiers (npm packages, stdlib) never resolve — they
 * aren't files in this repository, so no edge is produced for them.
 */
export function resolveImportPath(
  sourcePath: string,
  specifier: string,
  knownPaths: ReadonlySet<string>,
): string | null {
  if (!specifier.startsWith('.')) return null

  const base = posix.normalize(posix.join(posix.dirname(sourcePath), specifier))
  const candidates = [
    base,
    ...CANDIDATE_EXTENSIONS.map((ext) => base + ext),
    ...CANDIDATE_EXTENSIONS.map((ext) => posix.join(base, 'index' + ext)),
  ]
  return candidates.find((c) => knownPaths.has(c)) ?? null
}

import { UndirectedGraph } from 'graphology'
import louvainModule from 'graphology-communities-louvain'
import { and, inArray, isNull, or } from 'drizzle-orm'

/** louvain ships CJS-flavored typings that fight NodeNext default imports. */
type LouvainFn = (graph: UndirectedGraph) => Record<string, number>
const louvain = ((louvainModule as { default?: unknown }).default ??
  louvainModule) as LouvainFn
import { db } from '../db/client.js'
import {
  noteLinks,
  notes,
  repositories,
  repositoryFileImports,
  repositoryFiles,
  semanticEdges,
} from '../db/schema.js'

export type ResourceType = 'note' | 'code'

export interface GraphNode {
  id: string
  resourceType: ResourceType
  resourceId: string // vaultId for notes, repositoryId for code
  path: string
  type: string | null // note OKF type, or detected language for code
  tags: string[] // notes only, empty for code
  timestamp: string | null // notes only, null for code
  community: number
}

export interface GraphEdge {
  source: string
  target: string
  kind: 'extracted' | 'structural' | 'semantic'
}

export interface VaultGraph {
  nodes: GraphNode[]
  edges: GraphEdge[]
  /** Structural groups skipped because pairwise edges would explode (no silent caps). */
  cappedGroups: string[]
}

const STRUCTURAL_GROUP_CAP = 50

export interface GraphFilters {
  types?: string[]
  tags?: string[]
  since?: string
  until?: string
}

export interface GraphResourceSet {
  vaultIds: string[]
  repositoryIds: string[]
}

interface InternalNode {
  id: string
  resourceType: ResourceType
  resourceId: string
  path: string
  type: string | null
  tags: string[]
  timestamp: string | null
}

function passesFilters(node: InternalNode, filters: GraphFilters): boolean {
  if (filters.types && (!node.type || !filters.types.includes(node.type))) return false
  if (filters.tags && !filters.tags.some((t) => node.tags.includes(t))) return false
  if (filters.since && (!node.timestamp || node.timestamp < filters.since)) return false
  if (filters.until && (!node.timestamp || node.timestamp > filters.until)) return false
  return true
}

/**
 * Assembles the graph for a set of vaults and repositories the caller
 * has already been authorized for (callers re-resolve access live —
 * audit rule). Notes and repository files are unioned into one node
 * set (spec 9) — same edge kinds, same Louvain pass, now spanning two
 * content types.
 */
export async function buildGraph(
  resources: GraphResourceSet,
  filters: GraphFilters = {},
): Promise<VaultGraph> {
  const { vaultIds, repositoryIds } = resources
  if (vaultIds.length === 0 && repositoryIds.length === 0) {
    return { nodes: [], edges: [], cappedGroups: [] }
  }

  let internalNodes: InternalNode[] = []

  if (vaultIds.length > 0) {
    const noteRows = await db
      .select({
        id: notes.id,
        vaultId: notes.vaultId,
        path: notes.path,
        type: notes.type,
        frontmatter: notes.frontmatter,
      })
      .from(notes)
      .where(and(inArray(notes.vaultId, vaultIds), isNull(notes.deletedAt)))
    for (const r of noteRows) {
      const fm = r.frontmatter as { tags?: string[]; timestamp?: string }
      internalNodes.push({
        id: r.id,
        resourceType: 'note',
        resourceId: r.vaultId,
        path: r.path,
        type: r.type,
        tags: Array.isArray(fm.tags) ? fm.tags : [],
        timestamp: typeof fm.timestamp === 'string' ? fm.timestamp : null,
      })
    }
  }

  if (repositoryIds.length > 0) {
    const fileRows = await db
      .select({
        id: repositoryFiles.id,
        repositoryId: repositoryFiles.repositoryId,
        path: repositoryFiles.path,
        language: repositoryFiles.language,
      })
      .from(repositoryFiles)
      .where(inArray(repositoryFiles.repositoryId, repositoryIds))
    for (const r of fileRows) {
      internalNodes.push({
        id: r.id,
        resourceType: 'code',
        resourceId: r.repositoryId,
        path: r.path,
        type: r.language,
        tags: [],
        timestamp: null,
      })
    }
  }

  internalNodes = internalNodes.filter((n) => passesFilters(n, filters))

  const byId = new Map(internalNodes.map((n) => [n.id, n]))
  const noteByVaultPath = new Map(
    internalNodes.filter((n) => n.resourceType === 'note').map((n) => [`${n.resourceId}:${n.path}`, n.id]),
  )
  const codeByRepoPath = new Map(
    internalNodes.filter((n) => n.resourceType === 'code').map((n) => [`${n.resourceId}:${n.path}`, n.id]),
  )
  const noteIds = internalNodes.filter((n) => n.resourceType === 'note').map((n) => n.id)
  const codeIds = internalNodes.filter((n) => n.resourceType === 'code').map((n) => n.id)

  // repo:<name>/<path> wikilinks resolve only against repositories already
  // in this call's own resource set — never a wider lookup.
  const repoNameToId =
    repositoryIds.length > 0
      ? new Map(
          (
            await db
              .select({ id: repositories.id, name: repositories.name })
              .from(repositories)
              .where(inArray(repositories.id, repositoryIds))
          ).map((r) => [r.name, r.id]),
        )
      : new Map<string, string>()

  const edges: GraphEdge[] = []
  const seen = new Set<string>()
  const addEdge = (a: string, b: string, kind: GraphEdge['kind']) => {
    if (a === b) return
    const key = a < b ? `${a}|${b}|${kind}` : `${b}|${a}|${kind}`
    if (seen.has(key)) return
    seen.add(key)
    edges.push({ source: a, target: b, kind })
  }

  if (noteIds.length > 0) {
    // EXTRACTED: plain wikilinks resolve within the source note's own
    // vault; a `repo:<name>/<path>` link resolves against a repository
    // already in this call's resource set (cross-type — spec 9).
    const links = await db.select().from(noteLinks).where(inArray(noteLinks.sourceNoteId, noteIds))
    for (const link of links) {
      const source = byId.get(link.sourceNoteId)
      if (!source) continue
      if (link.targetPath.startsWith('repo:')) {
        const [repoName, ...pathParts] = link.targetPath.slice('repo:'.length).split('/')
        const repositoryId = repoName ? repoNameToId.get(repoName) : undefined
        const targetId = repositoryId ? codeByRepoPath.get(`${repositoryId}:${pathParts.join('/')}`) : undefined
        if (targetId) addEdge(link.sourceNoteId, targetId, 'extracted')
        continue
      }
      const targetId = noteByVaultPath.get(`${source.resourceId}:${link.targetPath}`)
      if (targetId) addEdge(link.sourceNoteId, targetId, 'extracted')
    }
  }

  if (codeIds.length > 0) {
    // EXTRACTED: code imports resolved within the same repository.
    const imports = await db
      .select()
      .from(repositoryFileImports)
      .where(inArray(repositoryFileImports.sourceFileId, codeIds))
    for (const imp of imports) {
      if (imp.resolvedTargetFileId && byId.has(imp.resolvedTargetFileId)) {
        addEdge(imp.sourceFileId, imp.resolvedTargetFileId, 'extracted')
      }
    }
  }

  if (internalNodes.length > 0) {
    // Semantic: stored pairs (now spanning notes and code — spec 9)
    // filtered to the permitted, live node set.
    const allIds = [...byId.keys()]
    const sem = await db
      .select()
      .from(semanticEdges)
      .where(or(inArray(semanticEdges.nodeAId, allIds), inArray(semanticEdges.nodeBId, allIds)))
    for (const edge of sem) {
      if (byId.has(edge.nodeAId) && byId.has(edge.nodeBId)) {
        addEdge(edge.nodeAId, edge.nodeBId, 'semantic')
      }
    }
  }

  // Structural: notes group by type/tag (existing); code groups by
  // language (global, mirrors note type) and by top-level directory
  // (per-repository — "same folder" only means something within one repo).
  const cappedGroups: string[] = []
  const groups = new Map<string, string[]>()
  const addToGroup = (key: string, id: string) => {
    const list = groups.get(key)
    if (list) list.push(id)
    else groups.set(key, [id])
  }
  for (const n of internalNodes) {
    if (n.resourceType === 'note') {
      addToGroup(`type:${n.type}`, n.id)
      for (const tag of n.tags) addToGroup(`tag:${tag}`, n.id)
    } else {
      if (n.type) addToGroup(`language:${n.type}`, n.id)
      const topDir = n.path.includes('/') ? n.path.split('/')[0] : '.'
      addToGroup(`dir:${n.resourceId}:${topDir}`, n.id)
    }
  }
  for (const [key, ids] of groups) {
    if (ids.length > STRUCTURAL_GROUP_CAP) {
      // ponytail: pairwise edges for huge groups are an unreadable hairball;
      // color-by-type/tag/language conveys the grouping instead. Capped, reported.
      cappedGroups.push(key)
      continue
    }
    for (let i = 0; i < ids.length; i++) {
      for (let j = i + 1; j < ids.length; j++) addEdge(ids[i]!, ids[j]!, 'structural')
    }
  }

  // Louvain communities over the full assembled edge graph.
  const g = new UndirectedGraph()
  for (const id of byId.keys()) g.addNode(id)
  for (const e of edges) {
    if (!g.hasEdge(e.source, e.target)) g.addEdge(e.source, e.target)
  }
  const communities: Record<string, number> = g.order > 0 && g.size > 0 ? louvain(g) : {}

  const nodes: GraphNode[] = internalNodes.map((n) => ({
    ...n,
    community: communities[n.id] ?? 0,
  }))

  return { nodes, edges, cappedGroups }
}

